        command: 'gh repo clone ' + effectiveRepoInfo.owner + '/' +
                 effectiveRepoInfo.repo + ' ' + dir +
                 ' -- --no-tags --single-branch --branch ' + branchName +
                 ' --depth 200' +
                 ' && cd ' + dir +
