// recovery shapes eligible: a MERGED-PR issue a human reopened and a PR-less
// issue are fresh dev handoffs.
function hasOpenLinkedPr(q, item) {
    return !!(q.noOpenPr && item.pr && item.pr.state === 'OPEN');
}

