// ─ Fork-aware silent-update routing (gh-1070) ─────────────────
//
// update_branch's silent refresh is fork-blind: it clones and pushes the
// BASE repo, so a fork PR's head (the branch lives on the fork) fails 3×
// and gets flagged silent-update-degraded while the gh-757 guest park
// waits on the human author. GitHub grants the base-repo token a push to
// the fork's PR branch when the author left "Allow edits from maintainers"
// on (default on personal forks; the PR payload field is
// maintainer_can_modify/maintainerCanModify). Pure dispatch — smAgent
// probes and executes, this module only routes:

function forkSilentUpdateRoute(headRepoFull, baseOwner, baseRepo, maintainerCanModify) {
   // Three paths (UT-1): base (same-repo — zero behavior change),
   // fork (editable fork — machine merges main into the fork branch via
   // the maintainer-edit push), park (non-editable fork org fork —
   // gh-757 guest park, NO silent-update attempt: it can never succeed).
   var full = String(headRepoFull || '');
   var baseFull = String(baseOwner || '') + '/' + String(baseRepo || '');
   var forkFull = (full.indexOf('/') !== -1 && full !== baseFull) ? full : null;
   if (!forkFull) return { route: 'base', forkFull: null };
   if (maintainerCanModify === true) return { route: 'fork', forkFull: forkFull };
   return { route: 'park', forkFull: forkFull };
}

// The maintainer-edit push target: the FORK's token URL, built from
// head.repo.full_name — never the base repo for a fork head (UT-2). The
// token rides the child env (${GH_TOKEN}) exactly like the base-repush
// form, so the secret never appears in the script source.
function forkPushTokenUrl(forkFull) {
   return 'https://x-access-token:[REDACTED:Connection String Password]@github.com/' + forkFull + '.git';
}
