   // fork (editable fork — machine merges main into the fork branch via
   // the maintainer-edit push), park (non-editable fork org fork —
   // gh-757 guest park, NO silent-update attempt: it can never succeed).
   var full = String(headRepoFull || '');
   var baseFull = String(baseOwner || '') + '/' + String(baseRepo || '');
   var forkFull = (full.indexOf('/') !== -1 && full !== baseFull) ? full : null;
   if (!forkFull) return { route: 'base', forkFull: null };
   if (maintainerCanModify === true) return { route: 'fork', forkFull: forkFull };
   return { route: 'park', forkFull: forkFull };
