        var line = live.silentUpdateFailureLine(2, '2026-10-17T19:10:00Z');
        var out = live.silentUpdateFailureCount([line]);
        assert.deepEqual(out, { count: 2, newest: '2026-10-17T19:10:00Z' });
    });
});

