            '../../common/smAsync.js': smAsyncMod,
            '../../common/mutexRegistry.js': loadModule('js/common/mutexRegistry.js', makeRequire({}), {})
        }), mergedTools);
    }

    function pr(n, labels, mergeState, author) {
        return {
            number: n, labels: (labels || []).map(function (l) { return { name: l }; }),
